create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,major text,created_at timestamptz default now());
create table if not exists public.vocabulary(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,word text not null,phonetic text,part_of_speech text,definition text,example text,audio_url text,etymology text,memory_tip text,source text,created_at timestamptz default now(),unique(user_id,word));
create table if not exists public.review_items(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,vocabulary_id uuid references public.vocabulary(id) on delete cascade,due_at timestamptz default now(),interval_days integer default 1,ease numeric default 2.5,repetitions integer default 0,last_result text,created_at timestamptz default now());
create table if not exists public.learning_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,activity_type text not null,resource_id text,duration_seconds integer default 0,metadata jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists public.listening_materials(id uuid primary key default gen_random_uuid(),category text not null,title text not null,source text,source_url text,audio_url text,transcript text,translation text,difficulty text,license_note text,created_at timestamptz default now());
create table if not exists public.reading_articles(id uuid primary key default gen_random_uuid(),category text not null,title text not null,source text,source_url text,content text,translation text,created_at timestamptz default now());
create table if not exists public.speaking_attempts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,topic text,transcript text,feedback jsonb default '{}'::jsonb,audio_path text,created_at timestamptz default now());
create table if not exists public.error_patterns(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,category text not null,pattern text not null,example text,count integer default 1,last_seen_at timestamptz default now());
alter table public.profiles enable row level security;alter table public.vocabulary enable row level security;alter table public.review_items enable row level security;alter table public.learning_events enable row level security;alter table public.listening_materials enable row level security;alter table public.reading_articles enable row level security;alter table public.speaking_attempts enable row level security;alter table public.error_patterns enable row level security;
create policy "profiles own" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);create policy "vocabulary own" on public.vocabulary for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "reviews own" on public.review_items for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "events own" on public.learning_events for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "speaking own" on public.speaking_attempts for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "errors own" on public.error_patterns for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "public read listening" on public.listening_materials for select to anon,authenticated using(true);create policy "public read reading" on public.reading_articles for select to anon,authenticated using(true);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values(new.id) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.listening_materials(category,title,source,source_url,license_note) select 'BBC','BBC Learning English','BBC','https://www.bbc.co.uk/learningenglish','Official source link; follow BBC terms.' where not exists(select 1 from public.listening_materials where title='BBC Learning English');
insert into public.listening_materials(category,title,source,source_url,license_note) select 'VOA','VOA Learning English','VOA','https://learningenglish.voanews.com/','Official source link; follow VOA terms.' where not exists(select 1 from public.listening_materials where title='VOA Learning English');
insert into public.listening_materials(category,title,source,source_url,license_note) select 'TED','TED Talks','TED','https://www.ted.com/talks','Official source link; follow TED terms.' where not exists(select 1 from public.listening_materials where title='TED Talks');
